        //we may have terminators in some QT files (4 bytes set to 0 ...)
        while (parent->size>=8) {
                e = gf_isom_box_parse_ex(&a, bs, parent_type, GF_FALSE);
                if (e) {
                        if (a) gf_isom_box_del(a);
                        return e;
                }
                //sub box parsing aborted with no error
                if (!a) return GF_OK;

